<script setup>
import { computed } from 'vue';
import { Doughnut, Line } from 'vue-chartjs';
import { ArcElement, CategoryScale, Chart as ChartJS, Legend, LineElement, LinearScale, PointElement, Tooltip } from 'chart.js';
import AppLayout from '@/Components/AppLayout.vue';
ChartJS.register(ArcElement, CategoryScale, Legend, LineElement, LinearScale, PointElement, Tooltip);
const props = defineProps({ valuationDate: String, totalPlnGrosze: String, state: String, error: { default: null }, positions: { default: () => [] }, history: { default: () => [] }, allocation: { default: () => ({ byAssetClass: [], byHolding: [], availability: 'unavailable' }) }, kpis: { default: () => ({}) }, range: String });
const ranges = ['1D', 'WTD', 'MTD', '1M', '3M', 'YTD', 'MAX'];
const MAX_SAFE_INTEGER = String(Number.MAX_SAFE_INTEGER);
const isSafeIntegerString = (value) => typeof value === 'string' && /^\d+$/.test(value) && (value.length < MAX_SAFE_INTEGER.length || (value.length === MAX_SAFE_INTEGER.length && value <= MAX_SAFE_INTEGER));
const safeInteger = (value) => isSafeIntegerString(value) ? Number(value) : null;
const availableHistory = computed(() => props.history.filter((point) => point.availability === 'available' && safeInteger(point.totalPlnGrosze) !== null));
const valueChartData = computed(() => ({ labels: availableHistory.value.map((point) => point.date), datasets: [{ label: 'Value (PLN grosze)', data: availableHistory.value.map((point) => safeInteger(point.totalPlnGrosze)), borderColor: '#07865f', backgroundColor: '#d5f9eb', pointBackgroundColor: '#07865f', tension: .32, fill: true }] }));
const assetClassChartItems = computed(() => props.allocation.byAssetClass.filter((item) => safeInteger(item.valuePlnGrosze) !== null));
const allocationChartData = computed(() => ({ labels: assetClassChartItems.value.map((item) => item.assetClass), datasets: [{ data: assetClassChartItems.value.map((item) => safeInteger(item.valuePlnGrosze)), backgroundColor: ['#07865f', '#3b82f6', '#8b5cf6', '#f97316', '#64748b'], borderWidth: 0 }] }));
const allocationTotal = computed(() => props.allocation.byHolding.reduce((total, item) => total + Number(item.weightBps), 0));
const chartOptions = { responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { usePointStyle: true, font: { family: 'Inter, sans-serif' } } }, tooltip: { backgroundColor: '#14221d', padding: 12, cornerRadius: 10 } } };
const formatGrosze = (value) => value === null || value === undefined ? 'Unavailable' : `${value} PLN grosze`;
const percent = (bps) => `${(Number(bps) / 100).toFixed(2)}%`;
const rangeUrl = (range) => `/portfolio/valuation?date=${encodeURIComponent(props.valuationDate)}&range=${range}`;
</script>
<template><AppLayout><main class="app-content" aria-labelledby="portfolio-valuation-heading"><header class="flex flex-wrap items-end justify-between gap-5"><div><p class="eyebrow">Portfolio</p><h1 id="portfolio-valuation-heading" class="mt-1 text-3xl font-semibold tracking-tight text-ink-950">Valuation dashboard</h1><p class="mt-2 muted">As of <time :datetime="valuationDate">{{ valuationDate }}</time></p></div><nav class="flex flex-wrap gap-1 rounded-control border border-slate-200 bg-white p-1" aria-label="Valuation period"><a v-for="option in ranges" :key="option" :href="rangeUrl(option)" :aria-current="range === option ? 'page' : undefined" :class="[range === option ? 'bg-brand-600 text-white shadow-sm' : 'text-slate-600 hover:bg-slate-100', 'rounded-lg px-3 py-2 text-xs font-bold no-underline']">{{ option }}</a></nav></header><p v-if="error" class="notice notice-error mt-6" role="alert">{{ error }}</p><p v-else-if="state === 'empty'" class="notice notice-info mt-6" role="status">No confirmed positions are available for this valuation date.</p><section class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label="Portfolio metrics"><article v-for="metric in [{ label: 'Total value', value: formatGrosze(kpis.totalValuePlnGrosze) }, { label: 'Period return', value: kpis.periodReturnBps === null ? 'Unavailable' : `${kpis.periodReturnBps} bps` }, { label: 'Invested capital', value: formatGrosze(kpis.investedCapitalPlnGrosze) }, { label: 'Profit / loss', value: formatGrosze(kpis.profitLossPlnGrosze) }]" :key="metric.label" class="card"><h2 class="text-sm font-medium text-slate-500">{{ metric.label }}</h2><output class="mt-3 block text-xl font-semibold tracking-tight text-ink-950">{{ metric.value }}</output></article></section><section class="card mt-6" aria-labelledby="history-heading"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 id="history-heading" class="section-title">Value history</h2><p class="muted">{{ availableHistory.length }} available observations</p></div></div><Line v-if="availableHistory.length" :data="valueChartData" :options="chartOptions" class="mt-5 h-70" aria-label="Portfolio value history line chart"/><p v-else class="notice notice-info mt-5">No available valuation history for this range.</p><ul class="mt-5 divide-y divide-slate-100 text-sm"><li v-for="point in history" :key="point.date" class="flex flex-wrap justify-between gap-2 py-3"><span><time :datetime="point.date">{{ point.date }}</time> <span class="text-slate-400">({{ point.source }})</span></span><strong>{{ formatGrosze(point.totalPlnGrosze) }}</strong></li></ul></section><section class="mt-6 grid gap-6 lg:grid-cols-2" aria-label="Portfolio allocation"><article class="card"><h2 class="section-title">Allocation by holding</h2><p v-if="allocation.availability !== 'available'" class="notice notice-info mt-5">Allocation unavailable until every confirmed position has an exact valuation.</p><ul v-else class="mt-4 divide-y divide-slate-100"><li v-for="item in allocation.byHolding" :key="item.instrument" class="grid grid-cols-[1fr_auto] gap-2 py-3 text-sm"><span class="font-medium">{{ item.instrument }}<small class="mt-1 block text-slate-500">{{ formatGrosze(item.valuePlnGrosze) }}</small></span><strong>{{ percent(item.weightBps) }}</strong></li></ul><p v-if="allocation.availability === 'available'" class="mt-4 text-right text-sm font-semibold text-slate-500">{{ percent(allocationTotal) }}</p></article><article class="card"><h2 class="section-title">Allocation by asset class</h2><p v-if="allocation.availability !== 'available'" class="notice notice-info mt-5">Allocation unavailable.</p><Doughnut v-else :data="allocationChartData" :options="chartOptions" class="mt-5 h-70" aria-label="Asset class allocation donut chart"/></article></section><section class="card mt-6" aria-labelledby="positions-heading"><h2 id="positions-heading" class="section-title">Holdings</h2><div class="table-wrap mt-4"><table class="data-table"><caption class="sr-only">Confirmed position valuation details</caption><thead><tr><th>Instrument</th><th>Quantity</th><th>Price</th><th>FX</th><th>Value</th><th>Weight</th><th>Availability / diagnostics</th></tr></thead><tbody><tr v-for="position in positions" :key="position.instrument"><th scope="row" class="font-semibold text-ink-950">{{ position.instrument }}</th><td>{{ position.quantity }}</td><td>{{ position.sourcePrice.amount === null ? 'Unavailable' : `${position.sourcePrice.amount} ${position.sourcePrice.currency}` }}</td><td>{{ position.fx.status }}</td><td>{{ formatGrosze(position.plnGrosze) }}</td><td>{{ position.plnGrosze === null || allocation.availability !== 'available' ? 'Unavailable' : percent(allocation.byHolding.find((item) => item.instrument === position.instrument)?.weightBps) }}</td><td><strong>{{ position.availability }}</strong><ul v-if="position.diagnostics.length" class="mt-1 list-disc pl-4 text-xs text-slate-500"><li v-for="diagnostic in position.diagnostics" :key="diagnostic">{{ diagnostic }}</li></ul><span v-else class="text-slate-500">None</span></td></tr></tbody></table></div></section></main></AppLayout></template>
